public int sum(int n) {
  int s = 0;
  for (int i = 1; i <= n; i++) {
    s += i;
  }
  return s;
}

public int[] multTable(int n) {
  int[] res = new int[10];
  for (int i = 0; i < 10; i++) {
    res[i] = n * (i + 1);
  }
  return res;
}

public int powerOfTwo(int n) {
  int res = 1;
  for (int i = 0; i < n; i++) {
    res *= 2;
  }
  return res;
}

public boolean isPrime(int n) {
  if (n < 2) return false;
  for (int i = 2; i * i <= n; i++) {
    if (n % i == 0) return false;
  }
  return true;
}

public int digitSum(int n) {
  int sum = 0;
  while (n > 0) {
    sum += n % 10;
    n /= 10;
  }
  return sum;
}
